-- VISHWAS schema v1. Additive only: safe to run on an empty database; never
-- drops or rewrites data. IDs are generated by the server (crypto.randomUUID).

CREATE TABLE IF NOT EXISTS users (
  id UUID PRIMARY KEY,
  email TEXT NOT NULL,                 -- stored lower-cased
  full_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,         -- scrypt$N$r$p$salt$hash, never plaintext
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS users_email_key ON users (email);

-- Opaque bearer tokens; only their SHA-256 is stored.
CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  last_used_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions (user_id);

CREATE TABLE IF NOT EXISTS password_resets (
  token_hash TEXT PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ
);

-- One row per SOS. client_id is the app's session id, so retries never
-- create a second event. received_at proves the server got it.
CREATE TABLE IF NOT EXISTS sos_events (
  id UUID PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  client_id TEXT NOT NULL,
  trigger_source TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'resolved', 'cancelled')),
  started_at TIMESTAMPTZ NOT NULL,
  ended_at TIMESTAMPTZ,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  contacts JSONB,                      -- [{ contactId, name, phoneMasked }]
  alert_summary JSONB                  -- per-contact outcome as the app/provider reported it
);
CREATE UNIQUE INDEX IF NOT EXISTS sos_events_user_client_key ON sos_events (user_id, client_id);

CREATE TABLE IF NOT EXISTS sos_locations (
  id UUID PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES sos_events (id) ON DELETE CASCADE,
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL,
  accuracy_m REAL,
  recorded_at TIMESTAMPTZ NOT NULL,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sos_locations_event_idx ON sos_locations (event_id);

-- Files live on disk (STORAGE_DIR); the database keeps metadata + ownership.
CREATE TABLE IF NOT EXISTS recordings (
  id UUID PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  event_id UUID REFERENCES sos_events (id) ON DELETE SET NULL,
  kind TEXT NOT NULL CHECK (kind IN ('audio', 'video', 'photo')),
  part INTEGER NOT NULL,
  upload_key TEXT NOT NULL,            -- user/event/kind/part: an app retry never stores a file twice
  content_type TEXT NOT NULL,
  size_bytes BIGINT NOT NULL,
  sha256 TEXT NOT NULL,
  storage_key TEXT NOT NULL,           -- path relative to STORAGE_DIR, server-generated
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS recordings_upload_key ON recordings (upload_key);
CREATE INDEX IF NOT EXISTS recordings_user_idx ON recordings (user_id);
